(function(ns){'use strict';const U=ns.util,S=ns.store.state;const fields={name:'projectName',repository:'projectRepository',category:'projectCategory',status:'projectStatus',priority:'projectPriority',visibility:'projectVisibility',owner:'projectOwner',platform:'projectPlatform',stack:'projectStack',tags:'projectTags',summary:'projectSummary',paths:'projectPaths',dependencies:'projectDependencies',notes:'projectNotes'};function fromForm(){const old=S.projects.find(p=>p.id===S.editingProjectId),p=old?{...old}:ns.store.blankProject();for(const[k,id]of Object.entries(fields))p[k]=U.id(id).value.trim();p.updatedAt=U.now();return p}function toForm(p){S.editingProjectId=p?.id||null;for(const[k,id]of Object.entries(fields)){const el=U.id(id);if(el)el.value=p?.[k]||''}if(!p){U.id('projectStatus').value='Planning';U.id('projectPriority').value='Normal';U.id('projectVisibility').value='Private'}}function save(p){const i=S.projects.findIndex(x=>x.id===p.id);if(i>=0)S.projects[i]=p;else S.projects.unshift(p);S.selectedProjectId=p.id;S.editingProjectId=p.id;ns.store.save();return p}function remove(id){S.projects=S.projects.filter(p=>p.id!==id);for(const f of S.files)if(f.projectId===id)f.projectId='';if(S.selectedProjectId===id)S.selectedProjectId=null;if(S.editingProjectId===id)S.editingProjectId=null;ns.store.save()}function duplicate(id){const p=S.projects.find(x=>x.id===id);if(!p)return null;const c={...U.deepClone(p),id:U.uid(),name:p.name+' Copy',createdAt:U.now(),updatedAt:U.now(),fileIds:[]};S.projects.unshift(c);S.selectedProjectId=c.id;S.editingProjectId=c.id;ns.store.save();return c}function importData(data){const list=Array.isArray(data)?data:Array.isArray(data.projects)?data.projects:[data.project||data];let count=0;for(const raw of list){if(!raw||typeof raw!=='object'||!(raw.name||raw.projectName))continue;const p={...ns.store.blankProject(),...raw,name:raw.name||raw.projectName,id:raw.id||U.uid(),createdAt:raw.createdAt||U.now(),updatedAt:raw.updatedAt||U.now(),fileIds:Array.isArray(raw.fileIds)?raw.fileIds:[]};save(p);count++}return count}function exportData(){return{schema:ns.DEFAULTS.manifestSchema,version:ns.DEFAULTS.version,exportedAt:U.now(),projects:S.projects,files:S.files.map(({textPreview,...f})=>f)}}ns.directory={fields,fromForm,toForm,save,remove,duplicate,importData,exportData}})(window.UPAD);